from django.contrib.auth.models import User  # Создаём настоящих тестовых пользователей | from/import подключают указанные имена.
from django.test import TestCase, Client  # Получаем отдельную тестовую базу и HTTP-клиент | from/import подключают указанные имена.
from .forms import SearchForm, DEFAULT_PROFILE  # Проверяем серверную валидацию профиля | from/import подключают указанные имена.
from .matching import calculate_match  # Проверяем реальный алгоритм, без подмен и имитаций | from/import подключают указанные имена.
from .models import University, SavedUniversity  # Используем настоящие ORM-модели | from/import подключают указанные имена.
from .costs import calculate_costs  # Проверяем формулу личных расходов на обучение | from/import подключают указанные имена.
from .forms import CostForm, DEFAULT_COSTS  # Подключаем форму калькулятора и условный пример | from/import подключают указанные имена.
from django.core.management import call_command  # call_command запускает команду manage.py из Python; проверяем загрузку реального каталога | from/import подключают указанные имена.
from io import StringIO  # StringIO создаёт текстовый буфер в памяти; принимаем вывод команды без печати в терминал | from/import подключают указанные имена.
class UniPathTests(TestCase):  # Объединяем проверки пользовательских сценариев | class объявляет класс; имя в скобках — родитель, от которого наследуются возможности.
    def test_real_catalog_has_sources_and_is_repeatable(self):  # def объявляет тест; проверяем реальные записи, официальные ссылки и повторный запуск без дублей | def объявляет тестовый метод; self — текущий тестовый объект.
        call_command("seed_real", stdout=StringIO())  # call_command вызывает наполнение; stdout перенаправляет сообщения в StringIO | call_command — запускает команду Django из Python; stdout задаёт получателя её вывода | StringIO — текстовый буфер в памяти вместо отдельного файла.
        real = University.objects.filter(is_demo=False)  # filter возвращает QuerySet записей; is_demo=False выбирает реальные программы | filter — возвращает QuerySet записей, соответствующих именованным условиям.
        self.assertEqual(real.count(), 7)  # count считает записи; assertEqual сравнивает результат с ожидаемыми семью программами | assertEqual — проверяет равенство фактического и ожидаемого значений | count — считает записи QuerySet.
        for university in real:  # for перебирает каждую реальную программу для проверки обязательных сведений.
            self.assertTrue(university.source_url.startswith("https://"))  # startswith проверяет начало строки; assertTrue требует защищённую официальную ссылку | assertTrue — проверяет истинность выражения | startswith — проверяет, начинается ли строка с указанного текста.
            self.assertIsNotNone(university.verified_on)  # assertIsNotNone проверяет, что дата проверки заполнена | assertIsNotNone — проверяет, что значение не None.
            university.full_clean()  # full_clean запускает проверки полей модели и ограничений до сохранения данных | full_clean — запускает полную проверку модели; обычный save сам её не вызывает.
        call_command("seed_real", stdout=StringIO())  # Повторяем загрузку, чтобы проверить устойчивость к повторному запуску | call_command — запускает команду Django из Python; stdout задаёт получателя её вывода | StringIO — текстовый буфер в памяти вместо отдельного файла.
        self.assertEqual(University.objects.filter(is_demo=False).count(), 7)  # Повторная команда должна обновить те же записи без создания дублей | assertEqual — проверяет равенство фактического и ожидаемого значений | count — считает записи QuerySet | filter — возвращает QuerySet записей, соответствующих именованным условиям.
    def test_real_catalog_keeps_custom_data_and_demo_by_default(self):  # Проверяем, что обычная загрузка не удаляет записи пользователя и учебные примеры | def объявляет тестовый метод; self — текущий тестовый объект.
        call_command("seed_real", stdout=StringIO())  # Добавляем официальный каталог без разрешения на удаление старых примеров | call_command — запускает команду Django из Python; stdout задаёт получателя её вывода | StringIO — текстовый буфер в памяти вместо отдельного файла.
        self.assertTrue(University.objects.filter(pk=self.uni.pk).exists())  # exists проверяет наличие исходной пользовательской записи | assertTrue — проверяет истинность выражения | exists — проверяет наличие хотя бы одной подходящей записи | filter — возвращает QuerySet записей, соответствующих именованным условиям.
    def test_real_catalog_replaces_only_known_legacy_examples(self):  # Проверяем адресную очистку старого набора без удаления учётных записей и собственного контента | def объявляет тестовый метод; self — текущий тестовый объект.
        legacy = University.objects.create(name="Aster University · CS", country="Китай", city="Ханчжоу", major="cs", ielts=6, gpa=3, tuition=6000, description="Старый пример")  # create добавляет одну известную вымышленную запись для проверки удаления | create — создаёт и сохраняет новую запись модели.
        call_command("seed_real", replace_demo=True, stdout=StringIO())  # replace_demo=True включает явно запрошенную замену стандартных учебных примеров | call_command — запускает команду Django из Python; stdout задаёт получателя её вывода | StringIO — текстовый буфер в памяти вместо отдельного файла.
        self.assertFalse(University.objects.filter(pk=legacy.pk).exists())  # assertFalse подтверждает удаление известного старого примера | assertFalse — проверяет ложность выражения | exists — проверяет наличие хотя бы одной подходящей записи | filter — возвращает QuerySet записей, соответствующих именованным условиям.
        self.assertTrue(University.objects.filter(pk=self.uni.pk).exists())  # Собственная запись с другим названием должна остаться | assertTrue — проверяет истинность выражения | exists — проверяет наличие хотя бы одной подходящей записи | filter — возвращает QuerySet записей, соответствующих именованным условиям.
        self.assertTrue(User.objects.filter(pk=self.user.pk).exists())  # Учётная запись пользователя не должна удаляться при обновлении каталога | assertTrue — проверяет истинность выражения | exists — проверяет наличие хотя бы одной подходящей записи | filter — возвращает QuerySet записей, соответствующих именованным условиям.
    def test_real_program_page_shows_official_link(self):  # Проверяем доступность официального источника на существующей странице программы | def объявляет тестовый метод; self — текущий тестовый объект.
        call_command("seed_real", stdout=StringIO())  # Загружаем данные перед проверкой HTML | call_command — запускает команду Django из Python; stdout задаёт получателя её вывода | StringIO — текстовый буфер в памяти вместо отдельного файла.
        university = University.objects.filter(is_demo=False).first()  # first возвращает первый объект реального каталога | first — возвращает первый объект выборки или None | filter — возвращает QuerySet записей, соответствующих именованным условиям.
        response = self.client.get(f"/university/{university.pk}/")  # get имитирует открытие страницы; f-строка подставляет ID | get — метод тестового клиента: имитирует GET-запрос по адресу.
        self.assertContains(response, university.source_url)  # assertContains проверяет, что ссылка вуза присутствует в ответе | assertContains — проверяет наличие текста в успешном HTTP-ответе теста.
        self.assertContains(response, 'rel="noopener noreferrer"')  # Проверяем безопасное открытие внешнего источника существующим шаблоном | assertContains — проверяет наличие текста в успешном HTTP-ответе теста.
    def setUp(self):  # Перед каждым тестом создаём независимые исходные данные | def объявляет функцию/метод; self — текущий тест; создаёт независимые исходные объекты перед каждым тестовым методом.
        self.uni = University.objects.create(name="Test Campus", country="Китай", city="Тест", major="cs", ielts=6.5, gpa=4, tuition=15000, description="Учебный пример")  # Создаём вуз ровно на границах стартового профиля | create — создаёт и сохраняет новую запись модели.
        self.user = User.objects.create_user("student", password="StrongStudyPass2026!")  # Создаём обычного пользователя, пароль хранится как хеш | create_user — создаёт пользователя, хешируя переданный пароль.
    def test_equal_requirements_give_full_match(self):  # Ловим ошибку строгого сравнения > вместо >= | def объявляет тестовый метод; self — текущий тестовый объект.
        self.assertEqual(calculate_match(DEFAULT_PROFILE, self.uni)["score"], 100)  # Равенство требованиям должно давать все 100 баллов | assertEqual — проверяет равенство фактического и ожидаемого значений | calculate_match — наша функция: профиль и программа → баллы и объяснение четырёх сравнений.
    def test_failed_academics_do_not_become_admission_probability(self):  # Проверяем независимое начисление баллов и объяснения | def объявляет тестовый метод; self — текущий тестовый объект.
        result = calculate_match({**DEFAULT_PROFILE, "ielts": 6, "gpa": 3}, self.uni)  # Снижаем два академических показателя ниже требований | calculate_match — наша функция: профиль и программа → баллы и объяснение четырёх сравнений.
        self.assertEqual(result["score"], 40)  # Сохраняются только баллы за бюджет и специальность | assertEqual — проверяет равенство фактического и ожидаемого значений.
        self.assertEqual([item["passed"] for item in result["checks"]], [False, False, True, True])  # Причины должны совпадать с результатом | assertEqual — проверяет равенство фактического и ожидаемого значений.
    def test_form_rejects_invalid_ranges_and_unknown_choices(self):  # Проверяем ввод в обход HTML-ограничений | def объявляет тестовый метод; self — текущий тестовый объект.
        for invalid in [{"ielts": 10}, {"gpa": 6}, {"budget": -1}, {"major": "hacking"}, {"ielts": "nan"}, {"gpa": "inf"}]:  # Перебираем неправильные значения и нечисловые крайние случаи.
            with self.subTest(invalid=invalid):  # Показываем конкретное значение в случае ошибки теста | subTest — помечает отдельный случай внутри тестового цикла.
                self.assertFalse(SearchForm({**DEFAULT_PROFILE, **invalid}).is_valid())  # Сервер обязан отклонить некорректный профиль | assertFalse — проверяет ложность выражения | is_valid — проверяет форму и возвращает True/False; ошибки доступны в errors | SearchForm — класс проверки IELTS, GPA, бюджета, специальности и страны.
    def test_home_and_detail_render(self):  # Проверяем доступность публичных страниц | def объявляет тестовый метод; self — текущий тестовый объект.
        self.assertContains(self.client.get("/"), "Test Campus")  # Главная должна показывать запись из базы | assertContains — проверяет наличие текста в успешном HTTP-ответе теста | get — метод тестового клиента: имитирует GET-запрос по адресу.
        self.assertContains(self.client.get(f"/university/{self.uni.pk}/"), "Test Campus")  # Карточка должна показывать выбранный вуз | assertContains — проверяет наличие текста в успешном HTTP-ответе теста | get — метод тестового клиента: имитирует GET-запрос по адресу.
        self.assertEqual(self.client.get("/university/99999/").status_code, 404)  # Несуществующий вуз должен возвращать 404 | assertEqual — проверяет равенство фактического и ожидаемого значений | get — метод тестового клиента: имитирует GET-запрос по адресу.
    def test_country_filter_and_invalid_form(self):  # Проверяем фильтрацию и понятную реакцию на ошибки | def объявляет тестовый метод; self — текущий тестовый объект.
        response = self.client.get("/", {**DEFAULT_PROFILE, "country": "Китай"})  # Выполняем допустимый подбор по стране | get — метод тестового клиента: имитирует GET-запрос по адресу.
        self.assertEqual(response.context["total"], 1)  # В выборке должен остаться один подходящий стране вуз | assertEqual — проверяет равенство фактического и ожидаемого значений.
        response = self.client.get("/", {**DEFAULT_PROFILE, "ielts": 20})  # Отправляем заведомо недопустимый IELTS | get — метод тестового клиента: имитирует GET-запрос по адресу.
        self.assertEqual(response.context["total"], 0)  # Ошибка формы не должна выдавать ложные рекомендации | assertEqual — проверяет равенство фактического и ожидаемого значений.
        self.assertTrue(response.context["form"].errors)  # Пользователь должен получить сообщение об ошибке | assertTrue — проверяет истинность выражения.
    def test_save_requires_login_and_post(self):  # Проверяем, что изменения защищены и не выполняются через GET | def объявляет тестовый метод; self — текущий тестовый объект.
        self.assertEqual(self.client.post(f"/save/{self.uni.pk}/").status_code, 302)  # Гостя переводим на вход | assertEqual — проверяет равенство фактического и ожидаемого значений | post — метод тестового клиента: имитирует отправку POST-формы.
        self.client.force_login(self.user)  # Авторизуем тестового пользователя | force_login — авторизует пользователя в тестовом клиенте без проверки пароля.
        self.assertEqual(self.client.get(f"/save/{self.uni.pk}/").status_code, 405)  # Ссылка GET не должна сохранять или удалять данные | assertEqual — проверяет равенство фактического и ожидаемого значений | get — метод тестового клиента: имитирует GET-запрос по адресу.
    def test_save_duplicate_and_remove_are_safe(self):  # Проверяем повторный запрос и явное удаление | def объявляет тестовый метод; self — текущий тестовый объект.
        self.client.force_login(self.user)  # Выполняем действия от имени владельца | force_login — авторизует пользователя в тестовом клиенте без проверки пароля.
        for _ in range(2):  # Имитируем повторное нажатие на сохранение | range — создаёт последовательность целых чисел для цикла.
            self.client.post(f"/save/{self.uni.pk}/", {"action": "save"})  # Повторное сохранение должно быть идемпотентным | post — метод тестового клиента: имитирует отправку POST-формы.
        self.assertEqual(SavedUniversity.objects.filter(user=self.user).count(), 1)  # Дублирование записи запрещено | assertEqual — проверяет равенство фактического и ожидаемого значений | count — считает записи QuerySet | filter — возвращает QuerySet записей, соответствующих именованным условиям.
        self.client.post(f"/save/{self.uni.pk}/", {"action": "remove"})  # Явно просим удалить сохранение | post — метод тестового клиента: имитирует отправку POST-формы.
        self.assertFalse(SavedUniversity.objects.filter(user=self.user).exists())  # Проверяем, что связь исчезла | assertFalse — проверяет ложность выражения | exists — проверяет наличие хотя бы одной подходящей записи | filter — возвращает QuerySet записей, соответствующих именованным условиям.
    def test_saved_lists_are_private(self):  # Ловим утечку избранного другого пользователя | def объявляет тестовый метод; self — текущий тестовый объект.
        other = User.objects.create_user("other", password="AnotherStrongPass!")  # Создаём независимого владельца сохранения | create_user — создаёт пользователя, хешируя переданный пароль.
        SavedUniversity.objects.create(user=other, university=self.uni)  # Сохраняем вуз только для второго пользователя | create — создаёт и сохраняет новую запись модели.
        self.client.force_login(self.user)  # Открываем сайт от имени первого пользователя | force_login — авторизует пользователя в тестовом клиенте без проверки пароля.
        self.assertNotContains(self.client.get("/saved/"), "Test Campus")  # Чужое избранное не должно появиться в списке | assertNotContains — проверяет отсутствие текста в успешном HTTP-ответе | get — метод тестового клиента: имитирует GET-запрос по адресу.
        self.client.post(f"/save/{self.uni.pk}/", {"action": "remove"})  # Пытаемся удалить связь от другого имени | post — метод тестового клиента: имитирует отправку POST-формы.
        self.assertTrue(SavedUniversity.objects.filter(user=other).exists())  # Чужая связь должна сохраниться | assertTrue — проверяет истинность выражения | exists — проверяет наличие хотя бы одной подходящей записи | filter — возвращает QuerySet записей, соответствующих именованным условиям.
    def test_csrf_blocks_untrusted_post(self):  # Проверяем защиту от посторонней отправки формы | def объявляет тестовый метод; self — текущий тестовый объект.
        client = Client(enforce_csrf_checks=True)  # Включаем реальную проверку CSRF в тестовом клиенте | Client — тестовый клиент Django, имитирующий HTTP-запросы | enforce_csrf_checks — включение CSRF-проверок в тестовом клиенте.
        client.force_login(self.user)  # Создаём авторизованную сессию | force_login — авторизует пользователя в тестовом клиенте без проверки пароля.
        self.assertEqual(client.post(f"/save/{self.uni.pk}/", {"action": "save"}).status_code, 403)  # POST без CSRF-токена запрещён | assertEqual — проверяет равенство фактического и ожидаемого значений | post — метод тестового клиента: имитирует отправку POST-формы.
    def test_registration_login_logout(self):  # Проверяем полный цикл учётной записи | def объявляет тестовый метод; self — текущий тестовый объект.
        response = self.client.post("/register/", {"username": "newstudent", "password1": "PrivateCampus2026!", "password2": "PrivateCampus2026!"})  # Регистрируем нового пользователя | post — метод тестового клиента: имитирует отправку POST-формы.
        self.assertEqual(response.status_code, 302)  # После успешной регистрации ожидаем переход на вход | assertEqual — проверяет равенство фактического и ожидаемого значений.
        self.assertTrue(User.objects.filter(username="newstudent").exists())  # Учётная запись должна попасть в базу | assertTrue — проверяет истинность выражения | exists — проверяет наличие хотя бы одной подходящей записи | filter — возвращает QuerySet записей, соответствующих именованным условиям.
        self.client.post("/login/", {"username": "newstudent", "password": "PrivateCampus2026!"})  # Проверяем встроенную форму входа | post — метод тестового клиента: имитирует отправку POST-формы.
        self.assertEqual(self.client.get("/saved/").status_code, 200)  # После входа избранное доступно | assertEqual — проверяет равенство фактического и ожидаемого значений | get — метод тестового клиента: имитирует GET-запрос по адресу.
        self.client.post("/logout/")  # Выход выполняем безопасным POST-запросом | post — метод тестового клиента: имитирует отправку POST-формы.
        self.assertEqual(self.client.get("/saved/").status_code, 302)  # После выхода избранное снова требует входа | assertEqual — проверяет равенство фактического и ожидаемого значений | get — метод тестового клиента: имитирует GET-запрос по адресу.
    def test_costs_count_monthly_and_annual_payments_once(self):  # Ловим ошибку умножения годовых платежей на число месяцев | def объявляет тестовый метод; self — текущий тестовый объект.
        result = calculate_costs(DEFAULT_COSTS)  # Считаем пример: 15000 + 500×12 + 300×12 + 600 − 2000 | calculate_costs — наша функция: расходы → стипендия → оплата и остаток бюджета.
        self.assertEqual(result.get("total"), 25200)  # Полные расходы должны составить 25200 долларов | assertEqual — проверяет равенство фактического и ожидаемого значений | get — получает значение по ключу; второй аргумент — запасное значение при отсутствии ключа.
        self.assertEqual(result.get("needed"), 23200)  # После стипендии нужно покрыть 23200 долларов | assertEqual — проверяет равенство фактического и ожидаемого значений | get — получает значение по ключу; второй аргумент — запасное значение при отсутствии ключа.
